#pragma once

// The room story of seamless online co-op (docs/SEAMLESS.md 8): the story sets
// (data/online/story_sets.json, generated by tools/online/story_census.py and
// compiled in as src/engine/online_story_sets.inc), the member's pending set
// against the confirmed room story, the server's merge (the C# StoryMerge in
// server/DW4Online/src/DW4Online.Domain/Story does the same; the golden
// vectors of data/online/story_golden.json hold both to it) and the
// application of a barrier's room story to an engine.
//
// Plain data and functions: no Engine, so the DW4R2 client and its tests use
// it without a running game.
//
// The story of a record is BASE_FLAG (1024 x u8), BASE_FLAGFOLDER (12 x u8)
// and BASE_COUNTER (16 x i32). Of it the room merges
//   phase       flags 1-6 and 86, one-hot: the furthest phase wins (index 0 =
//               none, 1-6 = flag 1-6, 7 = flag 86);
//   persistent  the non-phase working set and every flag a script sets for
//               good: OR;
//   keys        flag folder 0-10 (key items): OR;
//   counters    COUNTER 1 and 7: additive, the growth of an engine line
//               (instance, visit) applied once;
// and derives after every merge the save room copies of the room's
// difficulty (phase, working set, keys) from them, as stagIS12's start.lua
// does, so a later gameStart.lua (which restores the working set from those
// copies) does not turn the story back. Everything else is never merged.

#include <array>
#include <cstdint>
#include <map>
#include <span>
#include <vector>

namespace dw4::engine {

// The story the room confirmed (8.4): the room owner's online story.
struct RoomStory {
    std::array<std::uint8_t, 1024> flags{};
    std::array<std::uint8_t, 12> folder{};
    std::array<std::int32_t, 16> counters{};
    std::uint32_t revision{};
    bool operator==(const RoomStory&) const = default;
};

// Story keys (a dropped set, 8.6, or the keys a merge refused): flags (the
// phase flags among them), key items, counters.
struct StoryKeys {
    std::vector<std::int32_t> flags;
    std::vector<std::int32_t> folder;
    std::vector<std::int32_t> counters;
    bool empty() const { return flags.empty() && folder.empty() && counters.empty(); }
    bool operator==(const StoryKeys&) const = default;
};

// The story values of an engine as it keeps them (Engine::flags(),
// GameSystem::flag_folder, Engine::counters()): sparse, an absent key reads 0
// (FLGisOn creates zero entries, so absent and 0 are both possible).
struct StoryValues {
    std::map<std::int32_t, std::uint8_t> flags;
    std::map<std::int32_t, std::uint8_t> folder;
    std::map<std::int32_t, std::int32_t> counters;
    bool operator==(const StoryValues&) const = default;
};

// The growth of an additive counter in one engine line (8.3): the line is the
// instance and visit the growth was made in (a fork's child counts from its
// fork under its own id), `growth` the cumulative growth since the line began.
struct CounterGrowth {
    std::int32_t counter{};
    std::uint32_t inst{}, visit{};
    std::int32_t growth{};
    bool operator==(const CounterGrowth&) const = default;
};

// A member's pending set (8.3): what its engine has beyond the confirmed room
// story. Sets: resends and duplicates from the members of one instance do no
// harm.
struct StoryDelta {
    std::uint8_t phase = 0;              // 0: no claim; else the engine's phase index (1-7), above the room's
    std::vector<std::int32_t> flags;     // persistent flags the room lacks (ascending)
    std::vector<std::int32_t> folder;    // key items the room lacks (ascending)
    std::vector<CounterGrowth> counters; // additive counters: the growth of engine lines
    bool empty() const { return phase == 0 && flags.empty() && folder.empty() && counters.empty(); }
    bool operator==(const StoryDelta&) const = default;
};

// Why the server did not take a key (STORY_ACK).
enum class StoryRefusal : std::uint8_t {
    none = 0,
    owner_away = 1,  // policy drop: refused and put into the room's dropped set
    held = 2,        // policy hold: kept by the server until the owner returns (not a loss)
    stage = 3,       // the sender's instance stage never sets it
    phase_jump = 4,  // more than one phase step beyond the room's
    rate = 5,        // too many STORY messages (sent again later)
    not_member = 6,  // the sender is in no stage instance
    not_story = 7,   // never merged (a temporary, derived or unknown value)
    limit = 8,       // a counter growth beyond the plausible, or a counter line the server never put the member in
    wait = 9,        // not yet: the visit is younger than the server's minimum or gave its phase step / key item (sent again)
};

// One refused key of a STORY_ACK.
struct StoryRefused {
    enum class Kind : std::uint8_t { phase = 0, flag = 1, folder = 2, counter = 3 };
    Kind kind{};
    std::int32_t index{}; // phase: the phase index; flag / folder / counter: its number
    StoryRefusal reason{};
    bool operator==(const StoryRefused&) const = default;
};

namespace story {

inline constexpr int kFlags = 1024, kFolder = 12, kCounters = 16;
inline constexpr int kPhases = 7;   // phase indexes 1-7
inline constexpr int kKeys = 11;    // flag folder 0-10
inline constexpr int kDifficulties = 3;

struct WorkingGroup {
    std::int32_t first{}, count{};
    std::array<std::int32_t, 3> copies{}; // the save room's copy of `first` per difficulty
};

// The sets (generated tables).
std::span<const std::int32_t> phase_flags();                  // 1-6, 86 (index 1-7)
std::span<const std::int32_t> phase_copies(int difficulty);   // the save room's copies of the phase flags
std::span<const WorkingGroup> working_groups();               // the non-phase working set with its copies
std::span<const std::int32_t> persistent_flags();             // OR (the non-phase working set included)
std::int32_t key_copy(int difficulty);                        // the copy of key 0 (key k at + k)
std::span<const std::int32_t> additive_counters();            // 1, 7
bool is_phase_flag(std::int32_t flag);
bool is_persistent(std::int32_t flag);
bool is_key(std::int32_t key);
bool is_additive(std::int32_t counter);
// The derived copies (never taken from a member): the phase copies, the
// working set copies and the key copies (0-11) of every difficulty.
bool is_copy(std::int32_t flag);

// Phase index 0-7 of a story (the furthest flag set; a record has at most one).
int phase(const RoomStory& story);
int phase(const StoryValues& values);

// The pending set of an engine against the confirmed story (8.3), without the
// counters (the session adds its engine line's growth): a higher phase, the
// persistent flags and key items the confirmed story lacks.
StoryDelta pending(const RoomStory& confirmed, const StoryValues& engine);

// Growth already applied per engine line (the server's memory of a room
// session): key (counter, inst, visit) -> cumulative growth taken.
struct LineKey {
    std::int32_t counter{};
    std::uint32_t inst{}, visit{};
    auto operator<=>(const LineKey&) const = default;
};
using StoryLines = std::map<LineKey, std::int32_t>;

// The server's merge of a delta into the room story (no plausibility, no
// owner policy: those are the room's): the phase rises to the delta's when it
// is at most one step above the room's (else refused, phase_jump), flags and
// keys are ORed (values outside the sets refused, not_story), a counter grows
// by the line's growth beyond what `lines` already took. Then the copies of
// `difficulty` are derived. `revision` rises by one when anything changed.
struct MergeResult {
    RoomStory story;
    std::vector<StoryRefused> refused;
    bool changed = false;
};
MergeResult merge(const RoomStory& room, const StoryDelta& delta, int difficulty, StoryLines& lines);

// The copies of `difficulty` from the working set and the keys (stagIS12's
// start.lua): phase copies one-hot as the phase, working copies = working
// flags, key copies 0-10 = keys 0-10.
void derive_copies(RoomStory& story, int difficulty);
// The working set and the keys from the copies of `difficulty` (gameStart.lua):
// the server does it when a room opens with that difficulty.
void rebase(RoomStory& story, int difficulty);

// A barrier's room story into an engine (8.5, 8.6): the phase rises to the
// room's (one-hot), persistent flags and keys the room has are set, counters
// rise to the room's; then the dropped values the engine holds are removed (a
// dropped phase falls back to the room's, one-hot; a dropped flag or key is
// cleared; a dropped counter takes the room's value). Only keys whose value
// changes are touched (FLGisOn creates zero entries and the fingerprint hashes
// every key). Returns whether a dropped value was removed (the notice).
bool apply(std::map<std::int32_t, std::uint8_t>& flags, std::map<std::int32_t, std::uint8_t>& folder,
           std::map<std::int32_t, std::int32_t>& counters, const RoomStory& room, const StoryKeys& dropped);
inline bool apply(StoryValues& values, const RoomStory& room, const StoryKeys& dropped) {
    return apply(values.flags, values.folder, values.counters, room, dropped);
}
// Whether apply would remove a dropped value from these values.
bool holds_dropped(const StoryValues& values, const RoomStory& room, const StoryKeys& dropped);

// The story blob of BARRIER_OK / STORY_ACK: flags 1024 B, folder 12 B,
// counters 16 x i32 LE (1,100 bytes; the revision travels beside it). An
// empty blob is no story.
inline constexpr std::size_t kStoryBytes = 1024 + 12 + 16 * 4;
std::vector<std::uint8_t> encode_story(const RoomStory& story);
RoomStory decode_story(std::span<const std::uint8_t> bytes, std::uint32_t revision); // throws std::runtime_error unless 1,100 bytes
// The dropped blob of BARRIER_OK: u16 n + n x u16 flags | u8 n + n x u8 keys |
// u8 n + n x u8 counters. An empty blob is an empty set.
std::vector<std::uint8_t> encode_keys(const StoryKeys& keys);
StoryKeys decode_keys(std::span<const std::uint8_t> bytes); // throws std::runtime_error on damaged bytes

} // namespace story

} // namespace dw4::engine
